 function renderFilters(){let container=document.getElementById('filters');let options=['Alles',...tiers.map(t=>t.name)];container.innerHTML=options.map(x=>`<button class="filter ${selected===x?'active':''}" data-filter="${x}" ${x!=='Alles'?`style="--tier:${tierFor(x).color}"`:''}>${x==='Alles'?`Alles (${ownedCount()}/75)`:`${x} (${pets.filter(p=>p.tier===x&&state.owned[p.id]).length}/${pets.filter(p=>p.tier===x).length})`}</button>`).join('');container.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{selected=b.dataset.filter;renderFilters();renderCatalog()})}
 function renderCatalog(){renderFilters();let query=(document.getElementById('search')?.value||'').trim().toLowerCase();let list=pets.filter(p=>(selected==='Alles'||p.tier===selected)&&(!query||p.name.toLowerCase().includes(query)));let cat=document.getElementById('catalog');cat.innerHTML=list.map(p=>{let got=state.owned[p.id],t=tierFor(p.tier);return `<article class="catalog-card ${got?'':'locked'} ${got&&got.count===1?'new-card':''}" title="${got?p.desc:'Broed dit ei uit om te ontdekken!'}"><span class="creature">${p.icon}</span><div class="pet-name">${got?p.name:'Onbekend wezen'}</div><div class="pet-tier" style="--tier:${t.color}">${got?p.tier:'???'}</div></article>`}).join('')||'<div class="empty">Geen huisdieren gevonden. Probeer een andere zoekopdracht ✨</div>'}
